# Try searching for the vacation plans file with different queries
files = search_files("Hawaii vacation plans")
if len(files) == 0:
    files = search_files("Hawaii vacation")
    if len(files) == 0:
        files = search_files("Hawaii")
        if len(files) == 0:
            raise ValueError("No file found related to Hawaii vacation plans.")

# Disambiguate if multiple files
if len(files) > 1:
    class VacationPlansFileSelection(BaseModel):
        file_id: str
    file_selection = query_ai_assistant(
        "Given these files, select the one that contains the vacation plans for Hawaii.",
        VacationPlansFileSelection
    )
    vacation_file = get_file_by_id(file_selection.file_id)
else:
    vacation_file = files[0]

# Step 1: Extract what is planned for June 13 from the vacation plans file
class VacationDayPlan(BaseModel):
    plan: str

june_13_plan = query_ai_assistant(
    "From the following document content, extract what is planned for June 13. Only return the plan for that day. Document content: {}".format(vacation_file.content),
    VacationDayPlan,
)
print("Plan for June 13 in Hawaii vacation:", june_13_plan.plan)

# Step 2: Find the other document in the drive that contains the packing list for the Hawaii vacation
packing_files = search_files("Hawaii packing")
if len(packing_files) == 0:
    packing_files = search_files("packing list")
    if len(packing_files) == 0:
        raise ValueError("No packing list file found for Hawaii vacation.")

# Disambiguate if multiple files
if len(packing_files) > 1:
    class PackingListFileSelection(BaseModel):
        file_id: str
    packing_file_selection = query_ai_assistant(
        "Given these files, select the one that contains the packing list for the Hawaii vacation.",
        PackingListFileSelection
    )
    packing_file = get_file_by_id(packing_file_selection.file_id)
else:
    packing_file = packing_files[0]

# Step 2: Extract the packing list from the packing file
class PackingListExtraction(BaseModel):
    packing_list: str

packing_list = query_ai_assistant(
    "Extract the packing list for the Hawaii vacation from the following document content. Only return the list. Document content: {}".format(packing_file.content),
    PackingListExtraction
)

# Step 2: Create a new file named 'hawaii-packing-list.docx' with the packing list
create_file("hawaii-packing-list.docx", packing_list.packing_list)
